WITH store_monthly AS (SELECT d.d_year, d.d_month_seq, SUM(ss.ss_net_profit) AS store_net_profit, COUNT(*) AS store_txn_count FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2000 AND 2005 GROUP BY d.d_year, d.d_month_seq), catalog_monthly AS (SELECT d.d_year, d.d_month_seq, cc.cc_division_name, SUM(cs.cs_net_profit) AS catalog_net_profit, COUNT(*) AS catalog_txn_count FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk WHERE d.d_year BETWEEN 2000 AND 2005 GROUP BY d.d_year, d.d_month_seq, cc.cc_division_name) SELECT cm.cc_division_name, cm.d_year, cm.d_month_seq, cm.catalog_net_profit, sm.store_net_profit, (cm.catalog_net_profit - sm.store_net_profit) AS profit_difference, cm.catalog_txn_count, sm.store_txn_count, ROW_NUMBER() OVER (PARTITION BY cm.cc_division_name ORDER BY cm.catalog_net_profit DESC) AS profit_rank FROM catalog_monthly cm JOIN store_monthly sm ON cm.d_year = sm.d_year AND cm.d_month_seq = sm.d_month_seq WHERE cm.catalog_net_profit > sm.store_net_profit ORDER BY cm.cc_division_name, profit_rank
